@import '@fontsource-variable/inter';
@import '@fontsource-variable/space-grotesk';
@import '@fontsource/bungee';

:root {
  --bg: #04060c;
  --panel: rgba(14, 18, 29, 0.72);
  --panel-solid: #0d111c;
  --line: rgba(255, 255, 255, 0.11);
  --line-bright: rgba(255, 255, 255, 0.2);
  --text: #f4f7ff;
  --muted: #8f99ae;
  --blue: #2d8cff;
  --cyan: #69e5ff;
  --violet: #9b6bff;
  --pink: #ff4d9d;
  --green: #4dffa6;
  --amber: #ffbd4a;
  --radius: 20px;
  --font: 'Inter Variable', 'Segoe UI', system-ui, sans-serif;
  --display: 'Space Grotesk Variable', 'Segoe UI', system-ui, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: var(--bg); color: var(--text); font-family: var(--font); }
body { -webkit-font-smoothing: antialiased; user-select: none; }
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }
a { color: inherit; text-decoration: none; }
svg { width: 20px; height: 20px; fill: currentColor; }
kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 24px; height: 22px; padding: 0 6px; border: 1px solid rgba(255,255,255,.25); border-radius: 6px; font: 700 10px var(--font); color: #fff; background: rgba(255,255,255,.07); }
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,.16); border-radius: 8px; }
::-webkit-scrollbar-track { background: transparent; }

#app { position: fixed; inset: 0; isolation: isolate; }
#room-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; z-index: 0; }
#room-vignette { position: absolute; inset: 0; z-index: 1; pointer-events: none; background:
  radial-gradient(ellipse at 64% 52%, transparent 0 22%, rgba(3,5,10,.12) 50%, rgba(3,5,10,.78) 100%),
  linear-gradient(90deg, rgba(3,5,10,.92) 0%, rgba(3,5,10,.5) 31%, transparent 62%),
  linear-gradient(0deg, rgba(3,5,10,.9) 0%, transparent 28%);
}
#app.room-off #room-canvas, #app.room-off #room-vignette, #app.room-off #room-ui, #app.room-off #room-topbar { opacity: .2; filter: blur(12px); }
#app.room-off #room-canvas { pointer-events: none; }

.topbar { position: fixed; z-index: 30; top: 0; left: 0; right: 0; display: flex; align-items: center; justify-content: space-between; padding: 24px 34px; transition: opacity .5s; }
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { font-family: var(--display); font-size: 28px; font-weight: 800; letter-spacing: -2px; line-height: 1; }
.brand-mark span { font-size: 17px; vertical-align: top; letter-spacing: -1px; margin-left: 1px; }
.brand-copy { display: flex; flex-direction: column; border-left: 1px solid var(--line-bright); padding-left: 12px; }
.brand-copy strong { font: 700 10px/1.2 var(--display); letter-spacing: 2.5px; }
.brand-copy small { font-size: 8px; letter-spacing: 1.3px; color: var(--muted); margin-top: 3px; }
.topbar-actions { display: flex; gap: 8px; }
.icon-btn { width: 40px; height: 40px; border: 1px solid var(--line); border-radius: 50%; display: grid; place-items: center; background: rgba(10,13,22,.35); color: #cfd6e5; backdrop-filter: blur(10px); transition: .2s; }
.icon-btn:hover { background: rgba(255,255,255,.12); color: #fff; transform: translateY(-1px); }
.icon-btn.muted { color: #555f73; }
.icon-btn.dark { background: rgba(255,255,255,.06); width: 38px; height: 38px; }

.room-ui { position: fixed; z-index: 20; inset: 0; display: flex; align-items: flex-end; justify-content: space-between; padding: 0 6vw 9vh 6vw; pointer-events: none; transition: opacity .5s, filter .5s; }
.room-ui button { pointer-events: auto; }
.room-copy { max-width: 570px; pointer-events: auto; animation: riseIn .9s .15s both cubic-bezier(.2,.8,.2,1); }
.eyebrow { display: flex; align-items: center; gap: 8px; font: 700 10px var(--display); letter-spacing: 2.8px; color: #a9b6cc; margin-bottom: 20px; }
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); display: inline-block; }
.room-copy h1 { font: 800 clamp(46px, 6.2vw, 98px)/.88 var(--display); letter-spacing: -.06em; margin: 0 0 25px; }
.room-copy h1 span { background: linear-gradient(100deg, #fff 10%, #78c8ff 55%, #a987ff 95%); -webkit-background-clip: text; background-clip: text; color: transparent; }
.room-copy p { color: #aab4c8; font-size: 14px; line-height: 1.65; max-width: 470px; margin: 0 0 30px; }
.room-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.primary-action, .secondary-action { display: flex; align-items: center; gap: 13px; padding: 13px 15px; min-width: 215px; border-radius: 14px; text-align: left; transition: .25s cubic-bezier(.2,.8,.2,1); position: relative; overflow: hidden; }
.primary-action { background: linear-gradient(135deg, #f7fbff, #d6e9ff); color: #061225; box-shadow: 0 15px 50px rgba(87,173,255,.28), inset 0 1px 0 #fff; }
.primary-action:hover { transform: translateY(-3px); box-shadow: 0 22px 65px rgba(87,173,255,.42); }
.secondary-action { background: rgba(12,18,30,.6); border: 1px solid rgba(255,255,255,.15); backdrop-filter: blur(14px); }
.secondary-action:hover { background: rgba(22,31,48,.8); border-color: rgba(255,255,255,.3); transform: translateY(-3px); }
.primary-action strong, .secondary-action strong { display: block; font-size: 13px; font-weight: 700; }
.primary-action small, .secondary-action small { display: block; font-size: 10px; opacity: .58; margin-top: 2px; }
.action-icon { width: 34px; height: 34px; border-radius: 10px; flex: none; position: relative; }
.power-icon { background: #07172d; }
.power-icon::before { content: ''; position: absolute; left: 50%; top: 8px; width: 11px; height: 11px; border: 2px solid #59c9ff; border-top-color: transparent; border-radius: 50%; transform: translateX(-50%); }
.power-icon::after { content: ''; position: absolute; left: 50%; top: 7px; width: 2px; height: 9px; background: #59c9ff; border-radius: 2px; transform: translateX(-50%); }
.disc-icon { background: rgba(255,255,255,.06); }
.disc-icon::before { content: ''; position: absolute; inset: 9px; border: 2px solid #d6e6ff; border-radius: 50%; }
.disc-icon::after { content: ''; position: absolute; inset: 15px; border: 1px solid #6fcfff; border-radius: 50%; }
.action-arrow { margin-left: auto; font-size: 20px; opacity: .55; }
.room-specs { display: flex; gap: 24px; margin-top: 28px; padding-top: 20px; border-top: 1px solid var(--line); max-width: 500px; }
.room-specs span { font: 700 8px var(--display); letter-spacing: 1.5px; color: #6e7b92; }
.room-specs b { color: #e8f0ff; font-size: 13px; margin-right: 3px; letter-spacing: 0; }
.room-tip { pointer-events: auto; max-width: 240px; padding: 18px; border-left: 1px solid rgba(105,229,255,.35); background: linear-gradient(90deg, rgba(30,65,95,.2), transparent); animation: riseIn 1s .4s both; }
.tip-index { font: 700 9px var(--display); letter-spacing: 2px; color: var(--cyan); }
.room-tip p { font-size: 11px; line-height: 1.65; color: #9ca9bf; margin: 9px 0 0; }
@keyframes riseIn { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }

.screen { position: fixed; inset: 0; z-index: 40; opacity: 0; pointer-events: none; transition: opacity .55s ease; }
.screen.active { opacity: 1; pointer-events: auto; }

#dashboard { background: linear-gradient(120deg, rgba(5,8,15,.92), rgba(7,12,22,.74)); backdrop-filter: blur(24px) saturate(1.15); overflow: hidden; }
.dash-glow { position: absolute; width: 60vw; height: 60vw; right: -20vw; top: -25vw; border-radius: 50%; background: radial-gradient(circle, rgba(45,140,255,.16), transparent 65%); pointer-events: none; }
.dash-top { position: relative; z-index: 2; display: flex; align-items: center; justify-content: space-between; padding: 22px 42px; }
.dash-brand { display: flex; align-items: center; gap: 8px; }
.ps-mark { font: 800 20px var(--display); letter-spacing: -1.4px; margin-right: 12px; }
.dash-divider { width: 1px; height: 20px; background: var(--line); margin-right: 10px; }
.dash-tab { font-size: 11px; font-weight: 600; letter-spacing: .4px; color: #8993a8; padding: 9px 12px; border-radius: 8px; transition: .2s; }
.dash-tab:hover { color: #fff; background: rgba(255,255,255,.06); }
.dash-tab.active { color: #fff; }
.dash-tab.active::after { content: ''; display: block; height: 2px; margin-top: 7px; background: #fff; border-radius: 2px; }
.dash-user { display: flex; align-items: center; gap: 10px; }
.dash-wallet { display: flex; align-items: baseline; gap: 5px; padding: 9px 13px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,.04); font-size: 11px; color: #9da8bd; transition: .2s; }
.dash-wallet:hover { background: rgba(255,255,255,.09); }
.dash-wallet b { font-size: 12px; color: #fff; }
.avatar { width: 35px; height: 35px; border-radius: 50%; display: grid; place-items: center; background: linear-gradient(145deg, #33405a, #151c2b); border: 1px solid rgba(255,255,255,.22); font: 700 11px var(--display); }
.dash-clock { display: flex; flex-direction: column; align-items: flex-end; margin: 0 5px 0 8px; }
.dash-clock b { font: 600 13px var(--display); }
.dash-clock span { font-size: 8px; color: #8f99ae; letter-spacing: 1px; }
.dash-main { position: relative; z-index: 2; display: grid; grid-template-columns: minmax(0, 1fr) 270px; gap: 18px; padding: 8px 42px 0; }
.dash-hero { position: relative; min-height: 344px; border-radius: 24px; overflow: hidden; background: #101522; border: 1px solid rgba(255,255,255,.12); box-shadow: 0 28px 80px rgba(0,0,0,.4); transition: transform .3s; }
.hero-art { position: absolute; inset: 0; background-size: cover; background-position: center; transform: scale(1.02); transition: transform 8s ease; }
.dash-hero:hover .hero-art { transform: scale(1.07); }
.hero-shade { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(6,9,16,.94) 0%, rgba(6,9,16,.65) 44%, rgba(6,9,16,.05) 78%), linear-gradient(0deg, rgba(4,7,13,.8), transparent 45%); }
.hero-content { position: absolute; left: 36px; bottom: 30px; z-index: 2; max-width: 470px; }
.hero-kicker { font: 700 9px var(--display); letter-spacing: 2.3px; color: var(--cyan); }
.hero-content h2 { font: 700 clamp(34px, 4vw, 54px)/.95 var(--display); letter-spacing: -.04em; margin: 10px 0 9px; text-transform: uppercase; }
.hero-content p { font-size: 12px; line-height: 1.55; color: #c1c9d8; margin: 0 0 12px; max-width: 390px; }
.hero-meta { display: flex; gap: 15px; color: #8d98ad; font: 600 8px var(--display); letter-spacing: 1.1px; margin-bottom: 18px; }
.hero-meta span { position: relative; }
.hero-meta span + span::before { content: '·'; position: absolute; left: -9px; }
.hero-actions { display: flex; gap: 9px; }
.pill-primary { background: #f3f8ff; color: #061225; padding: 12px 26px; border-radius: 999px; font-size: 12px; font-weight: 700; box-shadow: 0 7px 30px rgba(179,220,255,.22); transition: .2s; }
.pill-primary:hover { background: #fff; transform: translateY(-2px); box-shadow: 0 12px 40px rgba(179,220,255,.35); }
.pill-primary:disabled { opacity: .45; cursor: default; transform: none; }
.pill-ghost { background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.18); padding: 12px 21px; border-radius: 999px; font-size: 12px; font-weight: 600; backdrop-filter: blur(8px); transition: .2s; }
.pill-ghost:hover { background: rgba(255,255,255,.14); }
.hero-badge { position: absolute; top: 20px; right: 20px; z-index: 3; font: 700 8px var(--display); letter-spacing: 1.4px; padding: 7px 10px; border-radius: 6px; background: rgba(6,10,18,.7); border: 1px solid rgba(255,255,255,.18); backdrop-filter: blur(10px); }
.hero-badge.disc { color: var(--cyan); border-color: rgba(105,229,255,.35); }
.hero-index { position: absolute; right: 24px; bottom: 24px; z-index: 3; font: 600 9px var(--display); letter-spacing: 1.4px; color: rgba(255,255,255,.45); }
.dash-side { display: flex; flex-direction: column; gap: 12px; }
.side-panel { background: rgba(16,21,33,.68); border: 1px solid var(--line); border-radius: 16px; padding: 14px 15px; backdrop-filter: blur(14px); }
.panel-head { display: flex; justify-content: space-between; align-items: center; font: 700 8px var(--display); letter-spacing: 1.4px; color: #8994a9; }
.panel-head b { color: var(--green); font-size: 7px; }
.session-big { display: flex; flex-direction: column; padding: 9px 0 10px; }
.session-big span { font: 600 30px/1 var(--display); letter-spacing: -.04em; }
.session-big small { font-size: 7px; letter-spacing: 1.5px; color: #6e798e; margin-top: 4px; }
.session-row { display: flex; align-items: center; gap: 6px; padding: 5px 0; font-size: 9px; color: #aeb8ca; border-top: 1px solid rgba(255,255,255,.05); }
.session-row b { margin-left: auto; color: #e5ebf8; font-size: 9px; }
.status-dot { width: 4px; height: 4px; border-radius: 50%; background: var(--blue); box-shadow: 0 0 6px var(--blue); }
.storage-bar { height: 3px; background: rgba(255,255,255,.09); border-radius: 3px; overflow: hidden; margin-top: 5px; }
.storage-bar i { display: block; height: 100%; width: 38%; background: linear-gradient(90deg, var(--blue), var(--cyan)); border-radius: 3px; transition: width .4s; }
.friend-panel { flex: 1; }
.friend { display: flex; align-items: center; gap: 8px; padding: 7px 0; border-top: 1px solid rgba(255,255,255,.05); }
.friend:first-of-type { margin-top: 5px; }
.friend-avatar { width: 26px; height: 26px; flex: none; border-radius: 50%; display: grid; place-items: center; font: 700 10px var(--display); }
.friend-avatar.a { background: linear-gradient(135deg,#ef7bb5,#5d3d91); }
.friend-avatar.b { background: linear-gradient(135deg,#46c7b8,#194b78); }
.friend-avatar.c { background: linear-gradient(135deg,#ffb450,#8e3d3d); }
.friend div { display: flex; flex-direction: column; min-width: 0; }
.friend b { font-size: 9px; font-weight: 600; }
.friend small { font-size: 7.5px; color: #778298; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.friend i { width: 5px; height: 5px; border-radius: 50%; margin-left: auto; flex: none; }
.friend i.online { background: var(--green); box-shadow: 0 0 6px var(--green); }
.store-cta { display: flex; align-items: center; gap: 10px; border-radius: 14px; padding: 12px 14px; background: linear-gradient(110deg, rgba(45,140,255,.23), rgba(155,107,255,.17)); border: 1px solid rgba(95,165,255,.25); text-align: left; transition: .2s; }
.store-cta:hover { background: linear-gradient(110deg, rgba(45,140,255,.34), rgba(155,107,255,.25)); }
.store-cta-icon { font: 800 8px var(--display); letter-spacing: .5px; padding: 6px; border: 1px solid rgba(255,255,255,.25); border-radius: 6px; }
.store-cta div { display: flex; flex-direction: column; }
.store-cta b { font-size: 10px; }
.store-cta small { font-size: 8px; color: #aab8cf; }
