  display: flex; align-items: center; gap: 4px; z-index: 12; pointer-events: none;
}
.vpad-grip {
  pointer-events: auto; touch-action: none; cursor: grab;
  width: 42px; height: 22px; display: grid; place-items: center;
  border-radius: 0 0 10px 10px; border: 1px solid rgba(255,255,255,.2); border-top: 0;
  background: rgba(8,13,22,.8); color: #93a6bf; font-size: 12px; line-height: 1;
}
.vpad-grip.dragging { cursor: grabbing; color: #04121f; background: #5de8ff; }
.vpad-tools { display: flex; gap: 4px; }
.vpad-tools button {
  pointer-events: auto; width: 27px; height: 27px; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.2); background: rgba(8,13,22,.8); color: #cfe1f5;
