}
.vpad-tools button:hover { background: rgba(93,232,255,.28); color: #fff; }

.vpad-key {
  pointer-events: auto; touch-action: none; -webkit-tap-highlight-color: transparent;
  display: grid; place-items: center; text-align: center;
  background: linear-gradient(180deg, rgba(35,45,62,.94), rgba(9,14,23,.96));
  border: 1px solid rgba(255,255,255,.22); color: #eaf1fb;
  border-radius: 12px; font: 700 11px var(--display); letter-spacing: .4px;
  box-shadow: 0 4px 12px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.15);
  transition: transform .07s, background .07s, box-shadow .07s, color .07s;
}
.vpad-key.pressed {
  transform: translateY(2px) scale(.96);
  background: linear-gradient(180deg, #e6f8ff, #8fd8ff); color: #04121f;
  box-shadow: 0 0 20px rgba(93,232,255,.7), inset 0 0 8px rgba(255,255,255,.8);
}

.vpad-shoulders { display: flex; gap: 6px; align-items: stretch; }
.vpad-shoulder { width: calc(var(--pad-key) * 1.05); height: calc(var(--pad-key) * .6); border-radius: 12px 12px 7px 7px; }
.vpad-trigger { width: calc(var(--pad-key) * 1.72); height: calc(var(--pad-key) * .78); border-radius: 13px; display: flex; flex-direction: column; gap: 0; }
.vpad-trigger b { font-size: 10px; line-height: 1.1; }
.vpad-trigger small { font-size: 6px; letter-spacing: .3px; color: #8fa0b8; font-weight: 600; }
.vpad-trigger.pressed small { color: #0b3346; }

.vpad-dpad { position: relative; width: calc(var(--pad-key) * 2.35); height: calc(var(--pad-key) * 2.35); }
.vpad-dpad .vpad-key { position: absolute; width: calc(var(--pad-key) * .78); height: calc(var(--pad-key) * .78); border-radius: 10px; font-size: 10px; }
.vpad-dpad .dpad-up { left: calc(50% - var(--pad-key) * .39); top: 0; }
.vpad-dpad .dpad-down { left: calc(50% - var(--pad-key) * .39); bottom: 0; }
.vpad-dpad .dpad-left { left: 0; top: calc(50% - var(--pad-key) * .39); }
.vpad-dpad .dpad-right { right: 0; top: calc(50% - var(--pad-key) * .39); }
.dpad-hub { position: absolute; left: 50%; top: 50%; width: calc(var(--pad-key) * .4); height: calc(var(--pad-key) * .4); transform: translate(-50%,-50%); border-radius: 50%; background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.12); }

.vpad-stick-wrap { display: flex; flex-direction: column; align-items: center; gap: 3px; }
.vpad-stick {
  position: relative; width: var(--pad-stick); height: var(--pad-stick); border-radius: 50%;
  pointer-events: auto; touch-action: none;
  background: radial-gradient(circle at 50% 36%, #2b3648, #080d15 72%);
  border: 1px solid rgba(255,255,255,.22);
  box-shadow: inset 0 0 18px rgba(0,0,0,.75), 0 6px 18px rgba(0,0,0,.42);
}
.vpad-stick::after { content: ''; position: absolute; inset: 11%; border-radius: 50%; border: 1px dashed rgba(255,255,255,.13); }
.vpad-stick.active { box-shadow: inset 0 0 20px rgba(93,232,255,.4), 0 0 24px rgba(93,232,255,.35); }
.vpad-knob {
  position: absolute; left: 50%; top: 50%; width: 47%; height: 47%; border-radius: 50%;
  transform: translate(-50%,-50%); pointer-events: none;
  background: radial-gradient(circle at 38% 30%, #ffffff, #a6b6ca 55%, #56657a);
  border: 1px solid rgba(255,255,255,.55);
  box-shadow: 0 4px 12px rgba(0,0,0,.5);
}
.vpad-stick-label { font: 700 7px var(--display); letter-spacing: 1.7px; color: #b9c8dc; }

.vpad-minirow { display: flex; gap: 5px; }
.vpad-mini {
  pointer-events: auto; touch-action: none; width: calc(var(--pad-key) * .64); height: calc(var(--pad-key) * .64);
  border-radius: 50%; display: grid; place-items: center; font-size: 11px;
  background: linear-gradient(180deg, rgba(35,45,62,.94), rgba(9,14,23,.96));
  border: 1px solid rgba(255,255,255,.2); color: #dbe8f8;
  box-shadow: 0 3px 9px rgba(0,0,0,.35);
  transition: .07s;
}
.vpad-mini.pressed { background: #8fd8ff; color: #04121f; box-shadow: 0 0 16px rgba(93,232,255,.7); }

.vpad-actions { display: grid; grid-template-columns: repeat(3, var(--pad-key)); grid-template-rows: repeat(3, var(--pad-key)); gap: 3px; place-items: center; }
.vpad-face { width: calc(var(--pad-key) * .92); height: calc(var(--pad-key) * .92); border-radius: 50%; display: flex; flex-direction: column; gap: 0; }
.vpad-face b { font-size: calc(var(--pad-key) * .38); line-height: 1; }
.vpad-face small { font-size: 6px; letter-spacing: .2px; color: #9fb0c8; font-weight: 600; }
.vpad-face.pressed small { color: #0b3346; }
.act-tri { grid-area: 1 / 2; }
.act-sq { grid-area: 2 / 1; }
.act-ci { grid-area: 2 / 3; }
.act-x { grid-area: 3 / 2; }

.vpad-center-bottom {
  position: absolute; left: 50%; bottom: 10px; transform: translateX(-50%);
  display: flex; flex-wrap: wrap; gap: 6px; align-items: center; justify-content: center;
  width: min(48vw, 470px); pointer-events: none;
}
.vpad-center-bottom .pill {
  pointer-events: auto; height: calc(var(--pad-key) * .58); padding: 0 11px; border-radius: 20px;
  font-size: 8px; letter-spacing: .5px;
}
.vpad-center-bottom .pill.wide { padding: 0 14px; }

.vpad-status {
  position: absolute; top: 26px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 16px; padding: 7px 15px;
  border-radius: 12px; background: rgba(6,10,18,.66); border: 1px solid rgba(255,255,255,.14);
  backdrop-filter: blur(10px); pointer-events: none;
}
.vpad-status > div { display: flex; flex-direction: column; gap: 1px; }
.vpad-status span { font: 700 6px var(--display); letter-spacing: 1.4px; color: #8fa0b8; }
.vpad-status b { font: 700 13px var(--display); color: #eaf2ff; }
.vpad-vital i { display: block; width: 92px; height: 6px; margin-top: 3px; border-radius: 4px; background: rgba(255,255,255,.14); overflow: hidden; }
.vpad-vital em { display: block; height: 100%; width: 100%; background: linear-gradient(90deg,#4dffa6,#9dffca); transition: width .2s; }

.vpad-cluster { position: absolute; bottom: 14px; display: flex; flex-direction: column; align-items: center; gap: 8px; pointer-events: none; }
.vpad-left { left: max(10px, 2vw); }
.vpad-right { right: max(10px, 2vw); }

/* ------------------------------ layout 2 ------------------------------ */
