.ds-dpad-up { left: 50%; top: 0; transform: translateX(-50%); }
.ds-dpad-down { left: 50%; bottom: 0; top: auto; transform: translateX(-50%); }
.ds-dpad-left { left: 0; top: 50%; transform: translateY(-50%); }
.ds-dpad-right { right: 0; left: auto; top: 50%; transform: translateY(-50%); }
.ds-dpad-hub { position: absolute; left: 50%; top: 50%; width: 30%; height: 26%; transform: translate(-50%,-50%); border-radius: 50%; background: #c9d1dc; box-shadow: inset 0 1px 2px rgba(0,0,0,.3); }
.ds-stick { width: 13%; aspect-ratio: 1; border-radius: 50%; background: radial-gradient(circle at 50% 36%, #2b3648, #080d15 72%); border: 1px solid rgba(0,0,0,.35); box-shadow: inset 0 0 14px rgba(0,0,0,.75), 0 3px 8px rgba(0,0,0,.4); }
