/* --------------------------- settings modal --------------------------- */
.pad-settings {
  width: min(980px, 96vw); max-height: 92vh; overflow: auto;
  background: rgba(9,14,23,.98); border: 1px solid rgba(255,255,255,.16);
  border-radius: 22px; padding: 26px; box-shadow: 0 40px 100px rgba(0,0,0,.7);
}
.pad-settings-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.pad-settings-head h2 { font: 700 clamp(28px, 4.6vw, 48px) var(--display); letter-spacing: -.045em; margin: 6px 0 6px; }
.pad-settings-head p { font-size: 10px; line-height: 1.55; color: #8fa0b8; max-width: 560px; margin: 0; }
.pad-card-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 20px 0 16px; }
.pad-card {
  position: relative; text-align: left; padding: 13px; border-radius: 16px;
