}
.pad-card:hover { border-color: rgba(93,232,255,.5); background: rgba(93,232,255,.07); }
.pad-card.active { border-color: rgba(93,232,255,.85); background: rgba(93,232,255,.1); box-shadow: 0 0 0 1px rgba(93,232,255,.35), 0 14px 34px rgba(0,0,0,.4); }
.pad-card-check { position: absolute; top: 10px; right: 10px; width: 20px; height: 20px; border-radius: 50%; background: #5de8ff; color: #04121f; display: grid; place-items: center; font-size: 11px; font-weight: 700; opacity: 0; transform: scale(.6); transition: .2s; }
