.pad-card-art { position: relative; display: block; height: 96px; border-radius: 11px; margin-bottom: 11px; overflow: hidden; border: 1px solid rgba(255,255,255,.08); background: radial-gradient(circle at 50% 45%, #1d2941, #060a11 78%); }
.pad-card b { display: block; font: 700 11px var(--display); letter-spacing: .5px; }
.pad-card small { display: block; font-size: 8px; line-height: 1.55; color: #8fa0b8; margin-top: 5px; }
.a-stick { position: absolute; width: 24px; height: 24px; border-radius: 50%; background: radial-gradient(circle at 38% 30%, #fff, #9aabc0 58%, #4c5a6e); border: 1px solid #b9c7d8; box-shadow: 0 2px 6px rgba(0,0,0,.5); }
.art-gta .a-stick.l { left: 20px; bottom: 14px; }
.art-gta .a-stick.r { right: 20px; bottom: 14px; }
.a-dpad { position: absolute; left: 26px; top: 15px; width: 18px; height: 18px; background: #cfd8e6; clip-path: polygon(35% 0,65% 0,65% 35%,100% 35%,100% 65%,65% 65%,65% 100%,35% 100%,35% 65%,0 65%,0 35%,35% 35%); }
.a-face { position: absolute; right: 26px; top: 17px; width: 9px; height: 9px; border-radius: 50%; background: #cfd8e6; box-shadow: 0 -11px 0 #cfd8e6, 0 11px 0 #cfd8e6, -11px 0 0 #cfd8e6, 11px 0 0 #cfd8e6; }
.a-box { position: absolute; bottom: 12px; width: 44px; height: 40px; border-radius: 8px; border: 2px dashed; }
.art-tutorial .a-box.l { left: 18px; border-color: rgba(77,255,166,.7); background: rgba(77,255,166,.08); }
.art-tutorial .a-box.r { right: 18px; border-color: rgba(186,124,255,.7); background: rgba(186,124,255,.1); }
.art-tutorial .a-stick { width: 20px; height: 20px; bottom: 22px; }
.art-tutorial .a-stick.l { left: 30px; }
.art-tutorial .a-stick.r { right: 30px; }
.a-ds { position: absolute; left: 50%; top: 50%; width: 118px; height: 46px; transform: translate(-50%,-50%); border-radius: 26px 26px 34px 34px; background: linear-gradient(180deg,#fff,#c4ccd9); box-shadow: 0 6px 14px rgba(0,0,0,.5); }
.a-pad { position: absolute; left: 50%; top: 50%; width: 30px; height: 14px; transform: translate(-50%,-90%); border-radius: 4px; background: linear-gradient(180deg,#22304a,#0a111b); box-shadow: 0 0 10px rgba(78,190,255,.9); }
.pad-settings-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.pad-toggle, .pad-scale { display: flex; align-items: center; gap: 11px; padding: 12px 14px; border-radius: 13px; background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.1); font-size: 10px; }
