.pad-scale em { font-style: normal; font: 700 10px var(--display); color: #5de8ff; }
.pad-settings-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.pad-settings-note { display: flex; gap: 9px; margin-top: 14px; padding: 12px 14px; border-radius: 11px; background: rgba(93,232,255,.07); border: 1px solid rgba(93,232,255,.18); font-size: 8px; line-height: 1.65; color: #9fb4cc; }
.pad-note-dot { flex: 0 0 auto; width: 7px; height: 7px; margin-top: 3px; border-radius: 50%; background: #5de8ff; box-shadow: 0 0 10px #5de8ff; }

.vpad-toast {
  position: fixed; left: 50%; top: 78px; z-index: 210; transform: translate(-50%,-12px);
  padding: 10px 18px; border-radius: 12px; text-align: center; pointer-events: none;
  background: rgba(8,13,22,.95); border: 1px solid rgba(93,232,255,.42);
  box-shadow: 0 16px 40px rgba(0,0,0,.55); opacity: 0; transition: .25s;
