637: function pollRealPad() {
638:   if (!navigator.getGamepads) return;
639:   let gp = null;
640:   try {
641:     for (const p of navigator.getGamepads()) {
642:       if (p && p.connected && isPlaystationPad(p.id)) { gp = p; break; }
643:     }
644:   } catch {}
645:   if (!gp) {
646:     if (realPad) {
647:       realPad = false;
648:       realPrev && Object.keys(realPrev).forEach((k) => delete realPrev[k]);
649:       updateVisibility();
650:       padToast('Controle desconectado', 'Controle virtual reativado.');
651:     }
652:     return;
653:   }
654:   if (!realPad) {
655:     realPad = true;
656:     updateVisibility();
657:     padToast('DualSense conectado', 'O controle virtual foi ocultado automaticamente.');
658:   }
659:   STD_BUTTONS.forEach((sem, i) => {
660:     const b = gp.buttons[i];
661:     const on = !!b && (b.pressed || b.value > 0.4);
662:     if (on && !realPrev[sem]) pressSem(sem);
663:     if (!on && realPrev[sem]) releaseSem(sem);
664:     realPrev[sem] = on;
665:   });
666:   const axes = gp.axes || [];
667:   const lx = deadzone(axes[0] || 0);
668:   const ly = deadzone(axes[1] || 0);
669:   const rx = deadzone(axes[2] || 0);
670:   const ry = deadzone(axes[3] || 0);
671:   state.stickL = { x: lx, y: ly };
672:   state.stickR = { x: rx, y: ry };
673:   applyMove(lx, ly);
674: }
