684:   if (Math.hypot(state.stickR.x, state.stickR.y) > 0.14) {
685:     virtualLook(state.stickR.x * 640 * dt, state.stickR.y * 640 * dt);
686:   }
687:   if (now - lastStatus > 400) {
688:     lastStatus = now;
689:     updateStatus();
690:   }
691: }
